import csv,json
B='<scratchpad>/c8base/legal_knowledge/curated_originals/'
KB={json.loads(l)['id']:json.loads(l) for l in open(B+'knowledge_base/v0.9/records_658.jsonl')}
CS={json.loads(l)['id']:json.loads(l) for l in open(B+'case_law/v0.9/cases_53.jsonl')}
sel={r['record_id']:r for r in csv.DictReader(open('<c8out>/E/work/sample_selection.csv'))}
AA='Army Act India Code compilation sha256 e47a4265813e95b491a24926428ed306cfeaae9013e7edb928cefef6e69a7c08 (GOVERNMENT_COMPILATION; no Gazette copy of 1950 Act held)'
AR='Army Rules India Code compilation sha256 48f52219121bf74d070bc832e4573f2f512b239e0a0441ba96b1daca2983a727 (GOVERNMENT_COMPILATION)'
AFT='AFT Act India Code compilation sha256 665863d1abb802f7488eb75f776946e30e72ccec16962da8e2b3ee8f2e023e3b'
F=["sample_no","record_id","record_type","domain","selection_basis","asserted_proposition_quote","supporting_source_refs","verification_against_held_authority","amendment_or_date_dependencies","inconsistent_linked_records","remaining_evidence_gap_class","prior_findings","c8_assessment","proposal_ref"]
rows=[]
def r(rid,dom,quote,refs,ver,dep,inc,gap,prior,assess,prop,manual=None):
    rec=KB.get(rid) or CS.get(rid)
    src=(rec.get('body','')+' '+rec.get('references','')) if rid in KB else ' '.join(str(v) for v in rec.values())
    assert quote in src, (rid,quote)
    s=sel.get(rid)
    basis=manual or (f"deterministic: score={s['score']} prior_P0P1={s['prior_P0P1']} missing_evidence_rows={s['missing_evidence_rows']}" if s and s['score'] else "deterministic: case with negative/qualifying later treatment in WS-B case_relations")
    rows.append(dict(zip(F,[len(rows)+1,rid,'KB' if rid in KB else 'CASE',dom,basis,quote,refs,ver,dep,inc,gap,prior,assess,prop])))
